        const runIds = [];
        const terminalIds = [];
        runner.subscribe((event) => {
            if (event.type === 'run' && event.status === 'completed') terminalIds.push(event.runId);
        });

        for (let index = 0; index < 101; index++) {
            runIds.push(await runner.start({ actionId: 'main', context, runInput: {} }));
